using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyCorruptDiceAmountBasedCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/PurifyCorruptDiceAmountBasedCustomDescription", order = 0)]
public class PurifyCorruptDiceAmountBasedCustomDescription : PurifyCorruptWithMultiplierCustomDescription
{
	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		PurifyCorruptDiceAmountBasedAction purifyCorruptDiceAmountBasedAction = battleAction as PurifyCorruptDiceAmountBasedAction;
		return Smart.Format(purifyCorruptDiceAmountBasedAction.GetDiceAmountOnlyFromHand ? base.localizationManager.GetLocalizedInYourHand(removeDotIfJapaneseOrTraditionalChinese: true) : base.localizationManager.GetLocalizedDieYouOwn(isTheAmountOf: false), purifyCorruptDiceAmountBasedAction.ExactName ? base.localizationManager.GetLocalizedString(purifyCorruptDiceAmountBasedAction.ExactNameID) : purifyCorruptDiceAmountBasedAction.DiceTier.GetLocalizedDiceTierWithDie());
	}
}
